// ---- dates.js ----
// Date handling. All dates are date-only ISO strings 'YYYY-MM-DD'.
// All arithmetic is done in UTC so the host timezone can never shift a day.

const ISO_RE = /^(\d{4})-(\d{2})-(\d{2})$/;
const UK_RE = /^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/;
const MS_PER_DAY = 86400000;

/** Build a UTC timestamp from y/m/d, or null if the calendar date is not real. */
function utcFromParts(y, m, d) {
  if (!Number.isInteger(y) || !Number.isInteger(m) || !Number.isInteger(d)) return null;
  if (m < 1 || m > 12 || d < 1 || d > 31) return null;
  const ts = Date.UTC(y, m - 1, d);
  const dt = new Date(ts);
  // Rejects 31 February style overflow, which JS would otherwise roll forward.
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== m - 1 || dt.getUTCDate() !== d) return null;
  return ts;
}

/** Format a UTC timestamp as 'YYYY-MM-DD'. */
function toISO(ts) {
  const d = new Date(ts);
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}`;
}

/**
 * Parse a value that came out of a spreadsheet cell into 'YYYY-MM-DD'.
 * Accepts ISO strings, UK dd/mm/yyyy, JS Dates and Google Sheets serial numbers.
 * Returns null rather than guessing when the value is ambiguous or invalid.
 * Never uses `new Date(string)`, whose parsing of '05/09/2026' is locale-dependent.
 */
function parseSheetDate(value) {
  if (value === null || value === undefined) return null;

  if (value instanceof Date) {
    if (Number.isNaN(value.getTime())) return null;
    return toISO(Date.UTC(value.getUTCFullYear(), value.getUTCMonth(), value.getUTCDate()));
  }

  // Google Sheets serial: days since 1899-12-30.
  if (typeof value === 'number') {
    if (!Number.isFinite(value) || value < 1 || value > 100000) return null;
    return toISO(Date.UTC(1899, 11, 30) + Math.floor(value) * MS_PER_DAY);
  }

  const s = String(value).trim();
  if (s === '') return null;

  const iso = ISO_RE.exec(s);
  if (iso) {
    const ts = utcFromParts(+iso[1], +iso[2], +iso[3]);
    return ts === null ? null : toISO(ts);
  }

  const uk = UK_RE.exec(s);
  if (uk) {
    const ts = utcFromParts(+uk[3], +uk[2], +uk[1]);
    return ts === null ? null : toISO(ts);
  }

  return null;
}

/** Timestamp for an ISO date string, or null. */
function tsOf(isoDate) {
  const m = ISO_RE.exec(String(isoDate ?? '').trim());
  if (!m) return null;
  return utcFromParts(+m[1], +m[2], +m[3]);
}

/** Whole days from `from` to `to`. Positive when `to` is later. */
function daysBetween(fromISO, toISOdate) {
  const a = tsOf(fromISO);
  const b = tsOf(toISOdate);
  if (a === null || b === null) return null;
  return Math.round((b - a) / MS_PER_DAY);
}

function addDays(isoDate, n) {
  const ts = tsOf(isoDate);
  if (ts === null) return null;
  return toISO(ts + n * MS_PER_DAY);
}

/** 0 = Sunday .. 6 = Saturday */
function dayOfWeek(isoDate) {
  const ts = tsOf(isoDate);
  return ts === null ? null : new Date(ts).getUTCDay();
}

function isWeekend(isoDate) {
  const d = dayOfWeek(isoDate);
  return d === 0 || d === 6;
}

function isBankHoliday(isoDate, holidays) {
  return Array.isArray(holidays) && holidays.includes(isoDate);
}

/**
 * The list of bank holiday dates for one division, from the gov.uk feed shape
 * ({ "england-and-wales": { events: [{ date: 'YYYY-MM-DD', ... }] }, ... }).
 * Returns [] for an unknown division or malformed data, never throws.
 */
function bankHolidayDates(data, division) {
  const events = data && data[division] && data[division].events;
  if (!Array.isArray(events)) return [];
  return events
    .map((e) => (e && typeof e.date === 'string' ? e.date : null))
    .filter((d) => d !== null && tsOf(d) !== null);
}

/** Is this date inside a configured quiet period such as the Christmas shutdown? */
function inQuietPeriod(isoDate, quietPeriods) {
  if (!Array.isArray(quietPeriods)) return false;
  const m = ISO_RE.exec(String(isoDate));
  if (!m) return false;
  const md = `${m[2]}-${m[3]}`;
  return quietPeriods.some((p) => {
    // A period may wrap the year end, e.g. 12-24 to 01-02.
    if (p.from <= p.to) return md >= p.from && md <= p.to;
    return md >= p.from || md <= p.to;
  });
}

/**
 * A day on which client email may be sent.
 * Returns { sendable: boolean, reason: string|null }.
 */
function sendableDay(isoDate, config) {
  if (tsOf(isoDate) === null) return { sendable: false, reason: 'invalid run date' };
  if (config.sendOnWeekends !== true && isWeekend(isoDate)) {
    return { sendable: false, reason: 'weekend' };
  }
  if (config.sendOnBankHolidays !== true && isBankHoliday(isoDate, config.bankHolidays)) {
    return { sendable: false, reason: 'bank holiday' };
  }
  if (inQuietPeriod(isoDate, config.quietPeriods)) {
    return { sendable: false, reason: 'quiet period' };
  }
  return { sendable: true, reason: null };
}

/**
 * The first day after `isoDate` on which email may be sent, or null if none is
 * found within `lookahead` days (for example an invalid config that forbids
 * every day). Used to bring a reminder forward when its date falls in a gap.
 */
function nextSendableDay(isoDate, config, lookahead = 21) {
  for (let i = 1; i <= lookahead; i += 1) {
    const d = addDays(isoDate, i);
    if (d === null) return null;
    if (sendableDay(d, config).sendable) return d;
  }
  return null;
}

/** 'Wednesday 14 October 2026' — how a UK client reads a date. */
function formatUKDate(isoDate) {
  const ts = tsOf(isoDate);
  if (ts === null) return String(isoDate ?? '');
  const days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'];
  const d = new Date(ts);
  return `${days[d.getUTCDay()]} ${d.getUTCDate()} ${months[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
}

// ---- rules.js ----
// Reminder rules. Nothing here is a statutory date. The due dates themselves
// come from the practice's own sheet; this file only decides which reminder a
// given number of days-to-go earns. See ../../rules/RULES.md.

/** Days before the due date at which a reminder is earned. A practice convention. */
const DEFAULT_MILESTONES = [30, 14, 7, 1];

const MAX_MILESTONE_DAYS = 366;

/**
 * Turn a configured list (array, or comma-separated string such as "30,14,7,1")
 * into a clean descending list of distinct whole numbers of days.
 * Anything unusable is dropped. If nothing usable is left the defaults are
 * returned and `valid` is false, so the caller can report it rather than
 * silently running on a setting nobody chose.
 */
function normaliseMilestones(value) {
  let items;
  if (Array.isArray(value)) items = value;
  else if (typeof value === 'string') items = value.split(',');
  else if (typeof value === 'number') items = [value];
  else items = [];

  const seen = new Set();
  let dropped = false;
  for (const raw of items) {
    const text = String(raw ?? '').trim();
    const n = /^\d+$/.test(text) ? Number(text) : NaN;
    if (Number.isInteger(n) && n >= 1 && n <= MAX_MILESTONE_DAYS) seen.add(n);
    else if (text !== '') dropped = true;
  }
  const list = [...seen].sort((a, b) => b - a);
  if (list.length === 0) return { milestones: [...DEFAULT_MILESTONES], valid: false };
  return { milestones: list, valid: !dropped };
}

/**
 * The reminder a deadline has earned, or null if it is still too far away.
 *
 * `daysUntilDue` is whole days from the run date to the due date. `gapDays` is
 * how many days pass before the next day on which email can go out (1 on an
 * ordinary weekday, 3 on a Friday before a bank-holiday-free weekend). A reminder
 * that would fall inside that gap is brought forward to today, because tomorrow's
 * run will not exist. The tightest milestone reached is returned, so a deadline
 * that has slipped past several milestones gets one reminder, not a burst.
 */
function milestoneFor(daysUntilDue, milestones, gapDays = 1) {
  if (!Number.isFinite(daysUntilDue) || !Array.isArray(milestones) || milestones.length === 0) {
    return null;
  }
  const gap = Number.isFinite(gapDays) && gapDays >= 1 ? gapDays : 1;
  const horizon = daysUntilDue - (gap - 1);
  const reached = milestones.filter((m) => m >= horizon);
  if (reached.length === 0) return null;
  return Math.min(...reached);
}

/** Read the "Last Reminder Sent" cell: a whole number of days, or null. */
function parseMilestoneCell(value) {
  if (value === null || value === undefined) return null;
  const s = String(value).trim();
  return /^\d+$/.test(s) ? Number(s) : null;
}

/** How urgent the wording should be for a milestone. */
function toneFor(milestone) {
  if (!Number.isFinite(milestone)) return 'reminder';
  if (milestone <= 1) return 'final';
  if (milestone <= 7) return 'urgent';
  if (milestone <= 14) return 'reminder';
  return 'advance';
}

const TONE_RANK = { advance: 0, reminder: 1, urgent: 2, final: 3 };
function toneRank(tone) {
  return TONE_RANK[tone] ?? 0;
}

// Status values. Only `active` rows are ever reminded about; the others each
// stop reminders for a different reason and are reported so nothing disappears.
const ACTIVE_STATUS = 'active';
const KNOWN_STATUSES = ['active', 'filed', 'cancelled', 'on hold'];

/**
 * Canonical status from a sheet cell. A blank cell means the deadline has not
 * been dealt with yet, so it is active. Returns null for an unrecognised word,
 * which the planner reports instead of guessing.
 */
function normaliseStatus(value) {
  const s = String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
  if (s === '' || s === 'pending' || s === 'open' || s === 'in progress' || s === 'active') return 'active';
  if (s === 'filed' || s === 'submitted' || s === 'done' || s === 'complete' || s === 'completed') return 'filed';
  if (s === 'cancelled' || s === 'canceled' || s === 'not required') return 'cancelled';
  if (s === 'on hold' || s === 'paused') return 'on hold';
  return null;
}

// Deliberately conservative: enough to catch the blank and obviously broken
// addresses that stop a send, without rejecting unusual but valid ones.
const EMAIL_RE = /^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/;

function isValidEmail(value) {
  const s = String(value ?? '').trim();
  return s.length > 0 && s.length <= 254 && EMAIL_RE.test(s);
}

// Addresses that ship in the examples. A live run using one of these would send
// client email from, or raise alerts to, an address nobody reads.
const PLACEHOLDER_DOMAINS = ['example.co.uk', 'example.com', 'yourfirm.co.uk', 'youraccountancyfirm.co.uk'];

function isPlaceholderEmail(value) {
  const s = String(value ?? '').trim().toLowerCase();
  const at = s.lastIndexOf('@');
  return at !== -1 && PLACEHOLDER_DOMAINS.includes(s.slice(at + 1));
}

/**
 * Problems with the two addresses a live run depends on: the sender, and the
 * practice address that receives the preview and every alert. Empty list when
 * both are real. Only enforced when dry run is off.
 */
function addressProblems(config) {
  const problems = [];
  for (const [label, value] of [['SENDER_EMAIL', config.senderEmail], ['PRACTICE_EMAIL', config.practiceEmail]]) {
    if (!isValidEmail(value)) problems.push(`${label} is empty or not a valid address`);
    else if (isPlaceholderEmail(value)) problems.push(`${label} is still the example placeholder (${String(value).trim()})`);
  }
  return problems;
}

// ---- copy.js ----
/**
 * Build the client-facing reminder for one contact and all their deadlines.
 *
 * Rules this copy obeys:
 *  - It reminds and asks for information. It does not state penalty amounts,
 *    rates or legal consequences, because those change and are not this kit's
 *    to assert. The practice adds its own engagement wording if it wants it.
 *  - The due date and the number of days go in the first lines, one ask only.
 *  - It never says the practice has filed, submitted or paid anything.
 *  - Every email says how to reach a person, and carries the fraud warning that
 *    makes a spoofed payment-details email easier for a client to spot.
 */
const LABELS = {
  advance: 'Advance notice',
  reminder: 'Reminder',
  urgent: 'Urgent reminder',
  final: 'Final reminder',
};

function whenPhrase(days) {
  if (days <= 0) return 'due today';
  if (days === 1) return 'due tomorrow';
  return `${days} days to go`;
}

/** The tone of an email is set by its most urgent deadline. */
function toneOfGroup(deadlines) {
  return deadlines.reduce((best, d) => {
    const t = toneFor(d.milestone);
    return toneRank(t) > toneRank(best) ? t : best;
  }, 'advance');
}

function buildEmail({ clientName, deadlines, config }) {
  const tone = toneOfGroup(deadlines);
  const label = LABELS[tone];
  const multiple = deadlines.length > 1;
  const nearest = deadlines.reduce((a, b) => (a.daysUntilDue <= b.daysUntilDue ? a : b));

  const schedule = deadlines
    .map((d) => `  ${d.deadlineType} — ${formatUKDate(d.dueDate)} (${whenPhrase(d.daysUntilDue)})`)
    .join('\n');

  const subject = multiple
    ? `${label}: ${deadlines.length} deadlines, the first ${formatUKDate(nearest.dueDate)}`
    : `${label}: ${nearest.deadlineType} deadline ${formatUKDate(nearest.dueDate)}`;

  let opening;
  let ask;
  if (tone === 'advance') {
    opening = multiple ? 'This is an early reminder of these upcoming deadlines:' : 'This is an early reminder of an upcoming deadline:';
    ask = 'Please start gathering any records or information we still need from you, and send them over when you can.';
  } else if (tone === 'reminder') {
    opening = multiple ? 'This is a reminder of these upcoming deadlines:' : 'This is a reminder of an upcoming deadline:';
    ask = 'If we are still waiting on anything from you, please send it to us as soon as you can so that there is time to deal with it before the date.';
  } else if (tone === 'urgent') {
    opening = multiple ? 'These deadlines are now close:' : 'This deadline is now close:';
    ask = 'If we are still waiting on anything from you, please send it to us within the next few days.';
  } else {
    opening = multiple ? 'These deadlines are imminent:' : 'This deadline is imminent:';
    ask = 'If we are still waiting on anything from you, please contact us today.';
  }

  const parts = [
    `Dear ${clientName},`, '',
    opening, '',
    schedule, '',
    ask, '',
    'If you have already sent us everything we need, thank you, and please ignore this message.',
    '', 'Kind regards,', config.signOffName || config.senderName, config.firmName,
    '', '—', footer(config),
  ];

  return { subject, body: parts.join('\n'), tone };
}

function footer(config) {
  const contact = config.firmPhone
    ? `If anything here looks wrong, please call us on ${config.firmPhone} before replying.`
    : 'If anything here looks wrong, please contact us before replying.';
  return [
    `${config.firmName}`,
    contact,
    'We will never ask you to change the bank details you pay us into by email. If you receive such a request, telephone us on a number you already hold before acting on it.',
  ].join('\n');
}

/** The internal pre-send digest: what will go out, and how to stop it. */
function buildDigest({ actions, skipped, runDate, config, haltReason, configWarning }) {
  const count = actions.length;

  const lines = actions.map((a) => {
    const refs = a.deadlines
      .map((d) => `${d.deadlineType} ${formatUKDate(d.dueDate)}`)
      .join('; ');
    return `  ${a.tone.toUpperCase().padEnd(8)} ${a.clientName} (${refs}) → ${a.realRecipient}`;
  });

  const body = [
    `Reminder run for ${formatUKDate(runDate)}.`,
    '',
    haltReason
      ? `NOTHING WILL BE SENT: ${haltReason}.`
      : count === 0
        ? 'No reminders are due today. No emails will be sent.'
        : `${count} email${count === 1 ? '' : 's'} will be sent at 09:00:`,
    '',
    ...lines,
    '',
    config.dryRun
      ? `DRY RUN IS ON. Nothing will reach a client. Every email above will be delivered to ${config.dryRunRecipient} instead. A dry run records no reminder as sent, so the same reminders will be planned again tomorrow, and the first live run will send whatever is due then.`
      : 'These will go to the real recipients above.',
  ];

  if (configWarning) body.push('', `Setting to check: ${configWarning}`);

  if (count > 0) {
    body.push('', "To stop today's run, type today's date (YYYY-MM-DD) in the Hold Until cell of the Run Control tab (row 2) before 09:00.");
  }

  if (skipped.length) {
    const grouped = {};
    for (const s of skipped) grouped[s.reason] = (grouped[s.reason] || 0) + 1;
    body.push('', 'Not reminded today:');
    for (const [reason, n] of Object.entries(grouped).sort()) {
      body.push(`  ${n} × ${reason}`);
    }
  }

  const needsAttention = skipped.filter((s) => s.needsAttention);
  if (needsAttention.length) {
    body.push('', 'Rows that need your attention in the sheet:');
    for (const s of needsAttention) {
      body.push(`  row ${s.rowNumber}: ${s.label || '(no client)'} — ${s.reason}`);
    }
  }

  body.push('', 'This kit only sends reminders. It never files or pays anything with HMRC or Companies House.');

  return {
    subject: `Reminder preview: ${count} email${count === 1 ? '' : 's'} at 09:00${config.dryRun ? ' (dry run)' : ''}`,
    body: body.join('\n'),
  };
}

